    "release": "20260310",
    "x86_64-linux": { "sha256": "REDACTED" },
    "aarch64-linux": { "sha256": "REDACTED" },
    "x86_64-darwin": { "sha256": "REDACTED" },
    "aarch64-darwin": { "sha256": "REDACTED/O8xqVAef0=" }
  }

